p=s/'e2e/workers.spec.ts';p.parent.mkdir(exist_ok=True);p.write_text('''import { test, expect } from '@playwright/test';
import type { Page } from '@playwright/test';
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';
const password=process.env.DEMO_PASSWORD!;
async function login(page:Page,email='client.admin@acme.example.com'){await page.goto('/');await page.getByLabel('Email',{exact:true}).fill(email);await page.getByLabel('Password',{exact:true}).fill(password);await page.getByRole('button',{name:'Sign in',exact:true}).click();await expect(page.getByRole('button',{name:'Add worker'})).toBeEnabled();}
async function add(page:Page,name:string,email:string){await page.getByRole('button',{name:'Add worker'}).click();await page.getByLabel('First name',{exact:true}).fill(name);await page.getByLabel('Last name',{exact:true}).fill('Learner');await page.getByLabel('Worker email',{exact:true}).fill(email);await page.getByLabel('Job title',{exact:true}).fill('Junior developer');await page.getByRole('button',{name:'Save worker',exact:true}).click();await expect(page.getByRole('status')).toContainText('Worker created.');await expect(page.getByRole('row').filter({hasText:email})).toBeVisible();}
test('CRUD persists through sign-out and sign-in, deletion is confirmed, and audit remains',async({page})=>{await login(page);await add(page,'Browser','browser-crud@example.test');let row=page.getByRole('row').filter({hasText:'browser-crud@example.test'});await row.getByRole('button',{name:'Edit',exact:true}).click();await page.getByLabel('First name',{exact:true}).fill('Updated');await page.getByRole('button',{name:'Save worker',exact:true}).click();await expect(row).toContainText('Updated Learner');await page.getByRole('button',{name:'Sign out'}).click();await login(page);row=page.getByRole('row').filter({hasText:'browser-crud@example.test'});await expect(row).toContainText('Updated Learner');page.once('dialog',d=>d.dismiss());await row.getByRole('button',{name:'Delete draft'}).click();await expect(row).toBeVisible();page.once('dialog',d=>d.accept());await row.getByRole('button',{name:'Delete draft'}).click();await expect(row).toHaveCount(0);await expect(page.locator('.audit')).toContainText('worker deleted');});
test('duplicate validation keeps a new draft and accepted directory unchanged',async({page})=>{await login(page);await add(page,'Original','browser-duplicate@example.test');await page.getByRole('button',{name:'Add worker'}).click();await page.getByLabel('First name',{exact:true}).fill('Proposal');await page.getByLabel('Last name',{exact:true}).fill('Retained');await page.getByLabel('Worker email',{exact:true}).fill('BROWSER-DUPLICATE@example.test');await page.getByRole('button',{name:'Save worker'}).click();await expect(page.getByRole('alert')).toContainText('already exists');await expect(page.getByLabel('First name',{exact:true})).toHaveValue('Proposal');await expect(page.getByRole('row').filter({hasText:'browser-duplicate@example.test'})).toHaveCount(1);});
test('two-tab stale edit retains its form until explicit current-data reload',async({page,context})=>{await login(page);await add(page,'Conflict','browser-conflict@example.test');const other=await context.newPage();await login(other);const row=page.getByRole('row').filter({hasText:'browser-conflict@example.test'});const otherRow=other.getByRole('row').filter({hasText:'browser-conflict@example.test'});await row.getByRole('button',{name:'Edit',exact:true}).click();await otherRow.getByRole('button',{name:'Edit',exact:true}).click();await page.getByLabel('First name',{exact:true}).fill('Winner');await other.getByLabel('First name',{exact:true}).fill('Proposal');await page.getByRole('button',{name:'Save worker'}).click();await expect(row).toContainText('Winner');await other.getByRole('button',{name:'Save worker'}).click();await expect(other.getByRole('alert')).toContainText('changed elsewhere');await expect(other.getByLabel('First name',{exact:true})).toHaveValue('Proposal');other.once('dialog',d=>d.dismiss());await other.getByRole('button',{name:'Load current worker'}).click();await expect(other.getByLabel('First name',{exact:true})).toHaveValue('Proposal');other.once('dialog',d=>d.accept());await other.getByRole('button',{name:'Load current worker'}).click();await expect(other.getByLabel('First name',{exact:true})).toHaveValue('Winner');await other.close();});
test('lifecycle removes draft deletion and ends in a read-only terminated profile',async({page})=>{await login(page);await add(page,'Lifecycle','browser-life@example.test');const row=page.getByRole('row').filter({hasText:'browser-life@example.test'});for(const next of ['onboarding','active','paused','active','terminated']){page.once('dialog',d=>d.accept());await row.getByRole('button',{name:'Move to '+next,exact:true}).click();await expect(row.locator('.badge')).toHaveText(next);}await expect(row.getByRole('button',{name:'Delete draft'})).toHaveCount(0);await row.getByRole('button',{name:'View',exact:true}).click();await expect(page.getByLabel('First name',{exact:true})).toBeDisabled();await expect(page.getByRole('button',{name:'Save worker'})).toHaveCount(0);});
test('tenant switch clears directory and excludes another organizations workers and activity',async({page})=>{await login(page);await add(page,'Private','browser-private@example.test');await page.getByRole('button',{name:'Sign out'}).click();await login(page,'client.admin@globex.example.com');await expect(page.locator('.identity')).toContainText('Globex Inc');await expect(page.getByRole('row').filter({hasText:'browser-private@example.test'})).toHaveCount(0);await expect(page.locator('.audit')).not.toContainText('worker created');});
test('server failure preserves the editor and does not show success',async({page})=>{await login(page);await page.getByRole('button',{name:'Add worker'}).click();await page.getByLabel('First name',{exact:true}).fill('Keep');await page.getByLabel('Last name',{exact:true}).fill('Draft');await page.getByLabel('Worker email',{exact:true}).fill('failed-save@example.test');await page.route('**/api/workers',async route=>{if(route.request().method()==='POST')await route.fulfill({status:503,contentType:'application/json',body:JSON.stringify({error:'Synthetic unavailable'})});else await route.continue();});await page.getByRole('button',{name:'Save worker'}).click();await expect(page.getByRole('alert')).toContainText('Synthetic unavailable');await expect(page.getByLabel('First name',{exact:true})).toHaveValue('Keep');await expect(page.getByRole('row').filter({hasText:'failed-save@example.test'})).toHaveCount(0);});
test('search empty state and literal names behave without interpreting markup',async({page})=>{await login(page);await add(page,'<b>Literal</b>','browser-literal@example.test');const row=page.getByRole('row').filter({hasText:'browser-literal@example.test'});await expect(row).toContainText('<b>Literal</b>');await expect(row.locator('b')).toHaveCount(0);await page.getByLabel('Search workers').fill('no-such-worker-unique');await page.getByRole('button',{name:'Search',exact:true}).click();await expect(page.getByText('No workers match this view.',{exact:false})).toBeVisible();await page.getByLabel('Search workers').fill('');await page.getByRole('button',{name:'Search',exact:true}).click();await expect(row).toBeVisible();});
test('desktop and narrow directory layouts remain usable with contained table scrolling',async({page})=>{await login(page);const out=process.env.WORKFORCE_VERIFY_RESULTS_DIR;if(out)mkdirSync(out,{recursive:true});for(const [label,width] of [['desktop',1440],['narrow',390]] as const){await page.setViewportSize({width,height:1000});expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await expect(page.getByRole('button',{name:'Add worker'})).toBeVisible();if(out)await page.screenshot({path:join(out,label+'.png'),fullPage:true});}});
''',encoding='utf-8');print('Wrote eight browser workflows and strict isolated servers')
